 def walk(o,path=''):
  if isinstance(o,dict):
   for k,v in o.items():
    if 'library' in k.lower() or 'rna' in k.lower() or 'strategy' in k.lower() or 'assay' in k.lower() or 'source' in k.lower() or 'file' in k.lower(): print(path+'/'+str(k), type(v).__name__)
    walk(v,path+'/'+str(k))
  elif isinstance(o,list):
   for i,v in enumerate(o[:5]): walk(v,path+f'[{i}]')
 walk(data)
PY"

