import json, urllib.request, urllib.parse, gzip, time, math, sys, concurrent.futures
from collections import defaultdict
BASE='https://federation.ccdi.cancer.gov/api/v1'
TARGET_SOURCES={'Treehouse','StJude','CCDI-DCC'}
PP=1000
OUT='/tmp/ccdi_rnaseq_file_footprint.json'

def fetch(path, params, timeout=90):
    url=BASE+path+'?'+urllib.parse.urlencode(params)
    req=urllib.request.Request(url, headers={'Accept-Encoding':'gzip','User-Agent':'codex-ccdi-footprint/1.0'})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        raw=r.read()
        if r.headers.get('Content-Encoding')=='gzip': raw=gzip.decompress(raw)
        return json.loads(raw.decode('utf-8'))

def ident_key(ident):
    ns=(ident or {}).get('namespace') or {}
    return (ns.get('organization'), ns.get('name'), (ident or {}).get('name'))

def source_item(payload, src):
    for item in payload:
        if item.get('source')==src:
            return item
    return None

print('Fetching RNA-Seq sample ID pages...')
sample_sets={src:set() for src in TARGET_SOURCES}
sample_errors=[]
# Get first page to know totals.
p1=fetch('/sample', {'library_strategy':'RNA-Seq','per_page':PP,'page':1})
totals={}
for src in sorted(TARGET_SOURCES):
    item=source_item(p1,src)
    if not item: continue
    if item.get('errors'):
